insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('85cf0131-f572-53e4-870b-ef905b05b576', 'Sé da diocese desde 1925. A página publica só missas; confissão e adoração, falar com a secretaria.', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=5","https://diocesedebraganca.com.br/paroquia/?paroquiaid=5","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('05a6e3de-cddc-5bcc-a4f4-3b061b223e18', 'Área pastoral criada em 2017, no bairro Águas Claras. A página da diocese não traz endereço da igreja nem horários. Fora do formato: A página cita a Capela Santa Rita, sem endereço nem horário. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=2","https://diocesedebraganca.com.br/paroquias/"}', ''),
  ('9da605d5-9d5e-5c89-9c22-87b35828fd95', 'A missa de quarta é na Capela Santo Expedito, sem endereço na fonte. Fora do formato: Quarta-feira, 19h30: missa na Capela Santo Expedito (sem endereço na fonte).', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=3","https://diocesedebraganca.com.br/paroquia/?paroquiaid=3","https://diocesedebraganca.com.br/paroquias/","https://diocesedebraganca.com.br/horarios-de-missa/"}', 'alta'),
  ('3819508d-e0c8-5174-a774-667e5107ef79', '', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=4","https://diocesedebraganca.com.br/paroquia/?paroquiaid=4","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('0338fc10-3582-5147-b30d-3a64112f176a', '', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=6","https://diocesedebraganca.com.br/paroquia/?paroquiaid=6","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('a87f3a33-56dc-5823-97fe-2bb8af18450a', 'Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=7","https://diocesedebraganca.com.br/paroquia/?paroquiaid=7","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('12c2fc68-bcbb-5377-96aa-04765363d9e2', 'Paróquia criada em 9 de julho de 2025, na zona rural de Bragança Paulista. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=8","https://diocesedebraganca.com.br/paroquia/?paroquiaid=8","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('8de716c7-2400-5f30-8315-5b105cfa91de', 'Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=9","https://diocesedebraganca.com.br/paroquia/?paroquiaid=9","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('bca861e8-f25d-5936-84d6-385ca1b8dc3a', '', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=10","https://diocesedebraganca.com.br/paroquia/?paroquiaid=10","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('6c1648c7-033a-5277-887e-1260496aed82', '', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=11","https://diocesedebraganca.com.br/paroquia/?paroquiaid=11","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('e7913786-d94c-50f4-9321-da7a77643fc2', '', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=12","https://diocesedebraganca.com.br/paroquia/?paroquiaid=12","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('fe4978f9-253e-515e-9572-7ecebec0a96a', 'Ficou sem o e-mail com o nome do pároco que a página traz.', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=13","https://diocesedebraganca.com.br/paroquia/?paroquiaid=13","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('77a1a290-2b00-54d7-a6e7-85253b5df8aa', 'A página lista também a comunidade Nossa Senhora do Bom Parto, Campo Largo, a mesma da paróquia de Fátima de Jarinu; ficou só lá. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=15","https://diocesedebraganca.com.br/paroquia/?paroquiaid=15","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('63ce7dbe-2642-54fb-bc18-9beff543caad', 'A missa das 9h de domingo é nas capelas, sem dizer qual. Fora do formato: Domingo, 9h: missa nas capelas Nossa Senhora Aparecida, São Sebastião, Nossa Senhora do Bom Sucesso e Nossa Senhora da Imaculada Conceição (a fonte não diz em qual nem onde ficam).', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=16","https://diocesedebraganca.com.br/paroquia/?paroquiaid=16","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
  ('3e941313-a299-5187-a448-14af5ddf7c6b', 'Paróquia criada em 29 de setembro de 2024. A página não traz telefone nem e-mail. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedebraganca.com.br/paroquia/?paroquiaid=17","https://diocesedebraganca.com.br/paroquia/?paroquiaid=17","https://diocesedebraganca.com.br/paroquias/"}', 'alta'),
