  ('cecc375a-8e19-552f-861a-01ea905d5efb', 'Fora do formato: Comunidade São Roque: domingo 9h. Comunidade São Vicente: domingo 7h30.', '{"https://www.arquidiocesecampinas.com.br/location/paroquia-sao-jose-2/","https://www.arquidiocesecampinas.com.br/location/paroquia-sao-jose-2/"}', 'alta'),
  ('760487a8-c099-533e-a658-0c4c2a8e97d8', 'Fora do formato: Dia 13 de cada mês: missa às 15h.', '{"https://www.arquidiocesecampinas.com.br/location/paroquia-senhor-bom-jesus-do-bonfim/","https://www.arquidiocesecampinas.com.br/location/paroquia-senhor-bom-jesus-do-bonfim/"}', 'alta'),
