  ('2f123aa8-13bd-54eb-a3f8-4b91211480da', 'Fora do formato: 1ª sexta-feira do mês, 19h30: missa votiva ao Sagrado Coração de Jesus.', '{"https://dj.org.br/paroquia/paroquia-santa-rosa-de-lima/"}', 'alta'),
  ('39f97929-b535-5a81-9f81-c53c95b94d45', 'Fora do formato: 1ª sexta-feira do mês: missa votiva ao Sagrado Coração de Jesus.; Missa uma vez por mês, às 19h30; a data se confirma na secretaria.', '{"https://dj.org.br/paroquia/paroquia-sao-pedro-apostolo/"}', 'alta'),
