  ('fea3440b-20ab-5447-bdde-f87d3c6fef83', '', '{"https://dj.org.br/paroquia/paroquia-santa-luzia-campo-limpo-paulista/"}', 'alta'),
  ('5971d8e7-4eb5-55f9-adf0-f8c0cd5f338b', '', '{"https://dj.org.br/paroquia/paroquia-santo-antonio-campo-limpo-paulista/"}', 'alta'),
