  ('787c5f3a-353c-54d4-9d36-85e844f9e424', 'A diocese publica só os horários da matriz.', '{"https://diocesedelimeira.org.br/paroquias/paroquia-de-nossa-senhora-do-carmo/","https://diocesedelimeira.org.br/paroquias/paroquia-de-nossa-senhora-do-carmo/"}', 'alta'),
  ('4c38d805-7a4d-5904-bc62-d7891382c9e1', '', '{"https://diocesedelimeira.org.br/paroquias/paroquia-de-sao-benedito-2/","https://diocesedelimeira.org.br/paroquias/paroquia-de-sao-benedito-2/"}', 'alta'),
  ('68e3d798-46a8-589e-96e0-b32a4fc70222', 'Na 1ª sexta do mês a missa das 7h passa para as 19h30.', '{"https://diocesedelimeira.org.br/paroquias/paroquia-de-sao-domingos/","https://diocesedelimeira.org.br/paroquias/paroquia-de-sao-domingos/"}', 'alta'),
  ('51aa8fac-5413-5154-b2cb-45d90c0cb6b6', '', '{"https://diocesedelimeira.org.br/paroquias/paroquia-de-sao-judas-tadeu/","https://diocesedelimeira.org.br/paroquias/paroquia-de-sao-judas-tadeu/"}', 'alta'),
